/**
 * migrate-sqlserver/reference-data.ts — TELLING THE SEED FROM THE OWNER'S
 * OWN WORK. THIS IS THE REAL DESIGN PROBLEM IN STAGE 2.
 *
 * Design §4.10b says the 62 issuers, 1,207 denominations, 15 catalogues, 15
 * metal contents, 9 mint marks and 2 categories are regenerated by
 * db/seed.ts on the first open and must NOT be migrated. It does not say how
 * to recognise them, and that is the whole difficulty:
 *
 *   copy everything  -> 'Sear' twice, 'Mexico' twice, '8 Reales' twice. The
 *                       last one is the dangerous one. A duplicated label
 *                       under one issuer makes every resolution of that text
 *                       AMBIGUOUS, and ambiguous resolves to NULL — so a
 *                       duplicated seed row does not add a denomination, it
 *                       DELETES one. migrations/seed-sql.ts's header says
 *                       this at length and it is the reason this file exists.
 *   copy nothing     -> the issuer he added by hand is gone, the catalogue
 *                       he soft-deleted comes back, his edits are reverted.
 *
 * *** THE METHOD. *** The seed is not a mystery: it is a reviewed file in
 * the tree, `migrations/seed-data/issuers-denominations.json`, plus the four
 * literal lists in db/seed.ts. The same file generated migration 013, which
 * is how those rows got into SQL Server in the first place. So every source
 * reference row is classified against it BY IDENTITY, never by id:
 *
 *   Issuers         Name
 *   Denominations   (issuer Name, Label)          <- not IssuerId
 *   Catalogs        Name
 *   Categories      CategoryName
 *   MetalContents   MetalContentName
 *   MintMarks       Label
 *
 * and lands in one of three buckets:
 *
 *   SEEDED, UNCHANGED  identity is in the seed and every other column still
 *                      matches what the seeder would have written. Skipped —
 *                      db/seed.ts already put an identical row there.
 *
 *   SEEDED, EDITED     identity is in the seed, something else differs. The
 *                      row already exists in the target, so it is UPDATED in
 *                      place, never inserted. This is the bucket that is
 *                      easy to forget, and the one that matters most in
 *                      practice: a catalogue the owner soft-deleted
 *                      (IsActive = 0) is a seeded row with one column
 *                      changed, and db/seed.ts deliberately never
 *                      resurrects it — but it would never have known it was
 *                      deleted unless this carried the 0 across.
 *
 *   HIS OWN            identity is not in the seed at all. INSERTED.
 *
 * *** AND THE IDS DO NOT TRAVEL. *** db/seed.ts's header spells this out:
 * re-seeding means `DenominationId` 412 on his SQL Server and
 * `DenominationId` 412 here are different denominations. Carrying the
 * integer across would attach his Morgan dollars to whatever happens to
 * occupy that id. So `Coins.DenominationId` and `Coins.CatalogId` are
 * re-resolved through the identity maps this file returns, and a source id
 * with no identity match is a hard failure rather than a NULL.
 *
 * TWO ASYMMETRIES THAT ARE NOT BUGS, AND ARE REPORTED RATHER THAN HIDDEN:
 *
 *   The JSON has grown since migration 013 generated the SQL Server seed
 *   (§4.10b counts 61 issuers and 1,161 denominations there; db/seed.ts now
 *   ships 70 and 1,207). Those extra rows exist in the target and not in the
 *   source. That is the re-seed working, and it means reference row counts
 *   are EXPECTED to differ between the two databases.
 *
 *   A row that was in an older JSON and has since been removed from it is
 *   classified as the owner's own and copied. That errs towards keeping
 *   data — a coin may still link to it — and it is counted separately in the
 *   report so the number can be sanity-checked.
 */

import type { SqliteBindValue, SqliteDatabase } from '../db/driver';
import {
  CATALOG_SEED,
  CATEGORY_SEED,
  METAL_CONTENT_SEED,
  MINT_MARK_SEED,
  readSeedFile,
} from '../db/seed';
import type { SeedFile } from '../migrations/seed-sql';
import { column, type SourceReader, type SourceRow } from './source-reader';
import {
  asFlag,
  asNullableNumber,
  asNullableText,
  asNumber,
  asText,
  identityKey,
  identityText,
} from './values';

/** Thrown for anything the operator has to fix before the migration can run. */
export class MigrationRefusedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MigrationRefusedError';
  }
}

/** Identity used for a denomination whose IssuerId is NULL. */
const NO_ISSUER = '\u0001<no issuer>';

/** Joins the two halves of a denomination's identity unambiguously. */
export function denominationKey(issuerName: string | null, label: string): string {
  return `${issuerName === null ? NO_ISSUER : identityKey(issuerName)}\u0000${identityKey(label)}`;
}

/** What happened to one reference table. */
export interface ReferenceOutcome {
  readonly table: string;
  readonly sourceRows: number;
  readonly seededUnchanged: number;
  readonly seededEdited: number;
  readonly ownAdded: number;
  /**
   * Rows that are not in the seed but were already in the target — a second
   * run after `--force`, or a row the owner also added on the SQLite side
   * while trying Stage 1. Updated, never inserted a second time, so the
   * tool is safe to re-run.
   */
  readonly ownUpdated: number;
  /** One line per row that was written, for the operator's log. */
  readonly changes: string[];
}

/** Everything the row copy needs afterwards. */
export interface ReferenceResult {
  readonly outcomes: ReferenceOutcome[];
  /** source DenominationId -> target DenominationId. */
  readonly denominationIdMap: Map<number, number>;
  /** source CatalogId -> target CatalogId. */
  readonly catalogIdMap: Map<number, number>;
  /**
   * source DenominationId -> the (issuer, label) it MEANS.
   *
   * The verification needs this rather than the id map: comparing the two
   * integers would only prove the copy used the map it was given, where
   * comparing what the ids mean proves the coin still points at the same
   * denomination.
   */
  readonly sourceDenominationKeyById: Map<number, string>;
  /** source CatalogId -> its Name, for the same reason. */
  readonly sourceCatalogNameById: Map<number, string>;
}

/** A reference table whose identity is one text column. */
interface SimpleSpec {
  readonly table: string;
  /** Written columns, in order. The FIRST is the identity column. */
  readonly columns: readonly string[];
  /** Seeded rows, keyed by identity. Values line up with `columns`. */
  readonly seed: Map<string, readonly SqliteBindValue[]>;
  /** Turns a source row into the same tuple shape. */
  readonly fromSource: (row: SourceRow) => readonly SqliteBindValue[];
}

/** Normalises a tuple element so the two sides are compared like for like. */
function comparable(value: SqliteBindValue): SqliteBindValue {
  return typeof value === 'string' ? value.trimEnd() : value;
}

function tuplesEqual(
  left: readonly SqliteBindValue[],
  right: readonly SqliteBindValue[]
): boolean {
  if (left.length !== right.length) return false;
  return left.every((value, index) => comparable(value) === comparable(right[index]));
}

/** The seed tuples for the five single-key tables, built from db/seed.ts. */
export function buildSimpleSeeds(seed: SeedFile): Record<string, SimpleSpec['seed']> {
  const issuers = new Map<string, readonly SqliteBindValue[]>();
  for (const issuer of seed.issuers) {
    issuers.set(identityKey(issuer.name), [
      identityText(issuer.name),
      issuer.isoCode,
      issuer.kind,
      issuer.validFrom,
      issuer.validTo,
      issuer.sortOrder,
      1,
    ]);
  }

  const catalogs = new Map<string, readonly SqliteBindValue[]>();
  CATALOG_SEED.forEach((name, index) => {
    catalogs.set(identityKey(name), [identityText(name), index + 1, 1]);
  });

  const categories = new Map<string, readonly SqliteBindValue[]>();
  for (const name of CATEGORY_SEED) {
    categories.set(identityKey(name), [identityText(name)]);
  }

  const metalContents = new Map<string, readonly SqliteBindValue[]>();
  METAL_CONTENT_SEED.forEach((name, index) => {
    metalContents.set(identityKey(name), [identityText(name), index + 1, 1]);
  });

  const mintMarks = new Map<string, readonly SqliteBindValue[]>();
  for (const mark of MINT_MARK_SEED) {
    mintMarks.set(identityKey(mark.label), [identityText(mark.label), mark.description, 1]);
  }

  return { Issuers: issuers, Catalogs: catalogs, Categories: categories, MetalContents: metalContents, MintMarks: mintMarks };
}

/** Reads a whole (small) source table into memory. Reference tables only. */
async function readTable(
  reader: SourceReader,
  table: string,
  columns: readonly string[]
): Promise<SourceRow[]> {
  const rows: SourceRow[] = [];
  await reader.forEachRow(
    { table, select: columns.map((name) => column(name)) },
    (row) => {
      rows.push(row);
    }
  );
  return rows;
}

/**
 * Classifies and applies one single-key reference table.
 *
 * The UPDATE and the INSERT both key on the identity column, which is
 * COLLATE NOCASE in db/schema.sql — so binding the lower-cased identity
 * finds the seeded row whatever case it was written in.
 */
function reconcileSimple(
  database: SqliteDatabase,
  spec: SimpleSpec,
  rows: readonly SourceRow[]
): ReferenceOutcome {
  const identityColumn = spec.columns[0];
  const insert = database.prepare(
    `INSERT INTO ${spec.table} (${spec.columns.join(', ')}) ` +
      `VALUES (${spec.columns.map(() => '?').join(', ')})`
  );
  const update = database.prepare(
    `UPDATE ${spec.table} SET ${spec.columns.map((name) => `${name} = ?`).join(', ')} ` +
      `WHERE ${identityColumn} = ?`
  );

  // Identities already in the target: the seeded rows db/seed.ts just wrote,
  // plus anything left behind by an earlier run. Consulted before every
  // insert, which is what makes this re-runnable without duplicating.
  const present = new Set<string>(
    database
      .prepare(`SELECT ${identityColumn} AS k FROM ${spec.table}`)
      .all()
      .map((row) => identityKey(String(row['k'])))
  );

  let seededUnchanged = 0;
  let seededEdited = 0;
  let ownAdded = 0;
  let ownUpdated = 0;
  const changes: string[] = [];
  const seen = new Set<string>();

  for (const row of rows) {
    const values = spec.fromSource(row);
    const key = identityKey(String(values[0]));

    if (seen.has(key)) {
      throw new MigrationRefusedError(
        `Source table ${spec.table} has two rows whose ${identityColumn} is ` +
          `${JSON.stringify(values[0])} once case and trailing spaces are ignored. ` +
          `SQLite's UNIQUE/PRIMARY KEY on that column is case-insensitive, so one ` +
          `of them could not be written -- and in Denominations the same situation ` +
          `would silently unlink every coin pointing at it. Resolve the duplicate ` +
          `in SQL Server first. Nothing has been written.`
      );
    }
    seen.add(key);

    const seeded = spec.seed.get(key);

    if (seeded && tuplesEqual(seeded, values)) {
      seededUnchanged += 1;
      continue;
    }

    // The identity column is written trimmed; see values.ts.
    const writable = values.map((value, index) =>
      index === 0 && typeof value === 'string' ? identityText(value) : value
    );

    if (present.has(key)) {
      const result = update.run(...writable, key);
      if (Number(result.changes) !== 1) {
        throw new MigrationRefusedError(
          `Expected exactly one ${spec.table} row with ${identityColumn} = ` +
            `${JSON.stringify(values[0])} to update, but ${result.changes} matched. ` +
            `Nothing further has been written.`
        );
      }
      if (seeded) {
        seededEdited += 1;
        changes.push(`updated seeded ${spec.table}: ${String(values[0])}`);
      } else {
        ownUpdated += 1;
        changes.push(`updated your ${spec.table}, already present: ${String(values[0])}`);
      }
      continue;
    }

    insert.run(...writable);
    present.add(key);
    ownAdded += 1;
    changes.push(`added your ${spec.table}: ${String(values[0])}`);
  }

  return {
    table: spec.table,
    sourceRows: rows.length,
    seededUnchanged,
    seededEdited,
    ownAdded,
    ownUpdated,
    changes,
  };
}

/** `Name -> IssuerId` for everything currently in the target. */
function targetIssuerIds(database: SqliteDatabase): Map<string, number> {
  const byKey = new Map<string, number>();
  for (const row of database.prepare('SELECT IssuerId, Name FROM Issuers').all()) {
    const key = identityKey(String(row['Name']));
    if (byKey.has(key)) {
      throw new MigrationRefusedError(
        `The target database has two issuers called ${JSON.stringify(row['Name'])}. ` +
          `That should be impossible (Issuers.Name is UNIQUE and COLLATE NOCASE); ` +
          `stop and look at the file before going further.`
      );
    }
    byKey.set(key, Number(row['IssuerId']));
  }
  return byKey;
}

/** `(issuer, label) -> DenominationId` for everything in the target. */
function targetDenominationIds(database: SqliteDatabase): Map<string, number> {
  const byKey = new Map<string, number>();
  const rows = database
    .prepare(
      'SELECT d.DenominationId AS id, d.Label AS label, i.Name AS issuerName ' +
        'FROM Denominations d LEFT JOIN Issuers i ON i.IssuerId = d.IssuerId'
    )
    .all();

  for (const row of rows) {
    const issuerName = row['issuerName'] === null ? null : String(row['issuerName']);
    const key = denominationKey(issuerName, String(row['label']));
    if (byKey.has(key)) {
      throw new MigrationRefusedError(
        `The target database already holds two denominations called ` +
          `${JSON.stringify(row['label'])} under ${issuerName ?? 'no issuer'}. ` +
          `An ambiguous label resolves to NULL, so this would silently unlink ` +
          `coins. Nothing further has been written.`
      );
    }
    byKey.set(key, Number(row['id']));
  }
  return byKey;
}

/** `Name -> CatalogId` for everything in the target. */
function targetCatalogIds(database: SqliteDatabase): Map<string, number> {
  const byKey = new Map<string, number>();
  for (const row of database.prepare('SELECT CatalogId, Name FROM Catalogs').all()) {
    byKey.set(identityKey(String(row['Name'])), Number(row['CatalogId']));
  }
  return byKey;
}

/**
 * Denominations, which need the issuer name on both sides before anything
 * can be compared. Run AFTER Issuers.
 */
function reconcileDenominations(
  database: SqliteDatabase,
  seed: SeedFile,
  sourceRows: readonly SourceRow[],
  sourceIssuerNameById: ReadonlyMap<number, string>,
  targetIssuers: ReadonlyMap<string, number>
): { outcome: ReferenceOutcome; sourceKeyById: Map<number, string> } {
  const issuerNameByKey = new Map<string, string>();
  for (const issuer of seed.issuers) issuerNameByKey.set(issuer.key, issuer.name);

  // The seeded denominations, keyed exactly as db/seed.ts wrote them.
  const seeded = new Map<string, readonly SqliteBindValue[]>();
  for (const denomination of seed.denominations) {
    const issuer = seed.issuers.find((candidate) => candidate.key === denomination.issuer);
    if (!issuer) continue;
    seeded.set(denominationKey(issuer.name, denomination.label), [
      identityText(denomination.label),
      issuer.isoCode ?? issuer.name,
      denomination.faceValue,
      denomination.sortOrder,
      1,
    ]);
  }

  const insert = database.prepare(
    'INSERT INTO Denominations (Label, Country, IssuerId, FaceValue, SortOrder, IsActive) ' +
      'VALUES (?, ?, ?, ?, ?, ?)'
  );
  const update = database.prepare(
    'UPDATE Denominations SET Label = ?, Country = ?, FaceValue = ?, SortOrder = ?, ' +
      'IsActive = ? WHERE DenominationId = ?'
  );

  let seededUnchanged = 0;
  let seededEdited = 0;
  let ownAdded = 0;
  let ownUpdated = 0;
  const changes: string[] = [];

  const sourceKeyById = new Map<number, string>();
  const seenKeys = new Set<string>();
  const targetIds = targetDenominationIds(database);

  for (const row of sourceRows) {
    const sourceId = asNumber(row, 'DenominationId');
    const label = asText(row, 'Label');
    const sourceIssuerId = asNullableNumber(row, 'IssuerId');

    let issuerName: string | null = null;
    if (sourceIssuerId !== null) {
      const found = sourceIssuerNameById.get(sourceIssuerId);
      if (found === undefined) {
        throw new MigrationRefusedError(
          `Source denomination ${sourceId} (${JSON.stringify(label)}) points at ` +
            `IssuerId ${sourceIssuerId}, which does not exist in Issuers. The link ` +
            `cannot be re-resolved by name, and guessing would attach coins to the ` +
            `wrong issuer. Fix it in SQL Server first. Nothing further has been written.`
        );
      }
      issuerName = found;
    }

    const key = denominationKey(issuerName, label);
    if (seenKeys.has(key)) {
      throw new MigrationRefusedError(
        `Source table Denominations has ${JSON.stringify(label)} twice under ` +
          `${issuerName ?? 'no issuer'}. Two rows with the same label under one ` +
          `issuer make every resolution of that text ambiguous, and ambiguous ` +
          `resolves to NULL -- so this does not add a denomination, it removes one ` +
          `(see migrations/seed-sql.ts). Resolve it in SQL Server first. Nothing ` +
          `further has been written.`
      );
    }
    seenKeys.add(key);
    sourceKeyById.set(sourceId, key);

    const values: readonly SqliteBindValue[] = [
      label,
      asText(row, 'Country'),
      asNullableNumber(row, 'FaceValue'),
      asNumber(row, 'SortOrder'),
      asFlag(row, 'IsActive'),
    ];

    const seedTuple = seeded.get(key);
    if (seedTuple && tuplesEqual(seedTuple, values)) {
      seededUnchanged += 1;
      continue;
    }

    const existingId = targetIds.get(key);

    if (seedTuple) {
      if (existingId === undefined) {
        throw new MigrationRefusedError(
          `${JSON.stringify(label)} under ${issuerName ?? 'no issuer'} is a seeded ` +
            `denomination but is not present in the target after seeding. That means ` +
            `db/seed.ts and this file disagree about the seed, which must be ` +
            `resolved before any coin links are written.`
        );
      }
      update.run(
        identityText(label),
        values[1],
        values[2],
        values[3],
        values[4],
        existingId
      );
      seededEdited += 1;
      changes.push(
        `updated seeded denomination: ${label} (${issuerName ?? 'no issuer'})`
      );
      continue;
    }

    if (existingId !== undefined) {
      // Not in the JSON, but already in the target — a second run after
      // --force, or a denomination added on the SQLite side while trying
      // Stage 1. Update rather than insert: inserting is the ambiguity trap
      // this whole file exists to avoid.
      update.run(
        identityText(label),
        values[1],
        values[2],
        values[3],
        values[4],
        existingId
      );
      ownUpdated += 1;
      changes.push(`updated your denomination, already present: ${label}`);
      continue;
    }

    const targetIssuerId =
      issuerName === null ? null : (targetIssuers.get(identityKey(issuerName)) ?? null);
    if (issuerName !== null && targetIssuerId === null) {
      throw new MigrationRefusedError(
        `Cannot place your denomination ${JSON.stringify(label)}: its issuer ` +
          `${JSON.stringify(issuerName)} is not in the target database, although ` +
          `issuers were migrated first. Nothing further has been written.`
      );
    }

    const inserted = insert.run(
      identityText(label),
      values[1],
      targetIssuerId,
      values[2],
      values[3],
      values[4]
    );
    // Recorded rather than re-queried: the map is how the next row knows
    // this one is already there, and re-reading 1,200 rows per insert would
    // be the same answer at a hundred times the cost.
    targetIds.set(key, Number(inserted.lastInsertRowid));
    ownAdded += 1;
    changes.push(`added your denomination: ${label} (${issuerName ?? 'no issuer'})`);
  }

  return {
    outcome: {
      table: 'Denominations',
      sourceRows: sourceRows.length,
      seededUnchanged,
      seededEdited,
      ownAdded,
      ownUpdated,
      changes,
    },
    sourceKeyById,
  };
}

/**
 * Moves the owner's reference data and returns the two id maps the coin copy
 * needs. Expects the target to have been opened and seeded already.
 */
export async function migrateReferenceData(
  reader: SourceReader,
  database: SqliteDatabase,
  seed: SeedFile = readSeedFile()
): Promise<ReferenceResult> {
  const seeds = buildSimpleSeeds(seed);
  const outcomes: ReferenceOutcome[] = [];

  // ----- Issuers, first, because Denominations is keyed on their names ----
  const issuerRows = await readTable(reader, 'Issuers', [
    'IssuerId',
    'Name',
    'IsoCode',
    'Kind',
    'ValidFrom',
    'ValidTo',
    'SortOrder',
    'IsActive',
  ]);

  const sourceIssuerNameById = new Map<number, string>();
  for (const row of issuerRows) {
    sourceIssuerNameById.set(asNumber(row, 'IssuerId'), asText(row, 'Name'));
  }

  outcomes.push(
    reconcileSimple(
      database,
      {
        table: 'Issuers',
        columns: ['Name', 'IsoCode', 'Kind', 'ValidFrom', 'ValidTo', 'SortOrder', 'IsActive'],
        seed: seeds['Issuers'],
        fromSource: (row) => [
          asText(row, 'Name'),
          asNullableText(row, 'IsoCode'),
          asText(row, 'Kind'),
          asNullableNumber(row, 'ValidFrom'),
          asNullableNumber(row, 'ValidTo'),
          asNumber(row, 'SortOrder'),
          asFlag(row, 'IsActive'),
        ],
      },
      issuerRows
    )
  );

  // ----- Denominations ----------------------------------------------------
  const denominationRows = await readTable(reader, 'Denominations', [
    'DenominationId',
    'Label',
    'Country',
    'IssuerId',
    'FaceValue',
    'SortOrder',
    'IsActive',
  ]);

  const denominations = reconcileDenominations(
    database,
    seed,
    denominationRows,
    sourceIssuerNameById,
    targetIssuerIds(database)
  );
  outcomes.push(denominations.outcome);

  // ----- Catalogs ---------------------------------------------------------
  const catalogRows = await readTable(reader, 'Catalogs', [
    'CatalogId',
    'Name',
    'SortOrder',
    'IsActive',
  ]);

  outcomes.push(
    reconcileSimple(
      database,
      {
        table: 'Catalogs',
        columns: ['Name', 'SortOrder', 'IsActive'],
        seed: seeds['Catalogs'],
        fromSource: (row) => [
          asText(row, 'Name'),
          asNumber(row, 'SortOrder'),
          asFlag(row, 'IsActive'),
        ],
      },
      catalogRows
    )
  );

  // ----- Categories -------------------------------------------------------
  outcomes.push(
    reconcileSimple(
      database,
      {
        table: 'Categories',
        columns: ['CategoryName'],
        seed: seeds['Categories'],
        fromSource: (row) => [asText(row, 'CategoryName')],
      },
      await readTable(reader, 'Categories', ['CategoryName'])
    )
  );

  // ----- MetalContents ----------------------------------------------------
  outcomes.push(
    reconcileSimple(
      database,
      {
        table: 'MetalContents',
        columns: ['MetalContentName', 'SortOrder', 'IsActive'],
        seed: seeds['MetalContents'],
        fromSource: (row) => [
          asText(row, 'MetalContentName'),
          asNumber(row, 'SortOrder'),
          asFlag(row, 'IsActive'),
        ],
      },
      await readTable(reader, 'MetalContents', [
        'MetalContentId',
        'MetalContentName',
        'SortOrder',
        'IsActive',
      ])
    )
  );

  // ----- MintMarks --------------------------------------------------------
  outcomes.push(
    reconcileSimple(
      database,
      {
        table: 'MintMarks',
        columns: ['Label', 'Description', 'IsActive'],
        seed: seeds['MintMarks'],
        fromSource: (row) => [
          asText(row, 'Label'),
          asNullableText(row, 'Description'),
          asFlag(row, 'IsActive'),
        ],
      },
      await readTable(reader, 'MintMarks', ['MintMarkId', 'Label', 'Description', 'IsActive'])
    )
  );

  // ----- The id maps ------------------------------------------------------
  const finalDenominations = targetDenominationIds(database);
  const denominationIdMap = new Map<number, number>();
  for (const [sourceId, key] of denominations.sourceKeyById) {
    const targetId = finalDenominations.get(key);
    if (targetId === undefined) {
      throw new MigrationRefusedError(
        `Source DenominationId ${sourceId} could not be matched to a row in the ` +
          `target by (issuer, label) after migrating reference data. Coin links ` +
          `cannot be re-resolved; nothing further has been written.`
      );
    }
    denominationIdMap.set(sourceId, targetId);
  }

  const finalCatalogs = targetCatalogIds(database);
  const catalogIdMap = new Map<number, number>();
  const sourceCatalogNameById = new Map<number, string>();
  for (const row of catalogRows) {
    const sourceId = asNumber(row, 'CatalogId');
    sourceCatalogNameById.set(sourceId, asText(row, 'Name'));
    const targetId = finalCatalogs.get(identityKey(asText(row, 'Name')));
    if (targetId === undefined) {
      throw new MigrationRefusedError(
        `Source CatalogId ${sourceId} (${asText(row, 'Name')}) could not be matched ` +
          `in the target by name. Nothing further has been written.`
      );
    }
    catalogIdMap.set(sourceId, targetId);
  }

  return {
    outcomes,
    denominationIdMap,
    catalogIdMap,
    sourceDenominationKeyById: denominations.sourceKeyById,
    sourceCatalogNameById,
  };
}
